using be;

namespace api;

// one company day off sent from the admin's "Add new holiday" form.
// id and holiday_type are not here: the id is generated by the db and the type is always Company
public class CompanyDayOffDTO
{
    public string name { get; set; }
    public DateOnly date { get; set; }

    public CompanyDayOffDTO()
    {
    }

    public DayOff to_day_off()
    {
        return new DayOff { name = name.Trim(), date = date, holiday_type = TypeOfHolidayDay.Company };
    }

    // returns null if the day off is valid, otherwise the error message
    public string? validate()
    {
        if (string.IsNullOrWhiteSpace(name))
        {
            return "name is required";
        }
        if (date == default)
        {
            return "date is required";
        }
        return null;
    }
}
